lay(100);  // \u56DE\u8DEF\u306E\u5B89\u5B9A\u5316\u3092\u5F85\u6A5F\n}\n\nvoid loop() {\n  // \u30D0\u30C3\u30C6\u30EA\u30FC\u76E3\u8996\u3092\u6709\u52B9\u5316\n  digitalWrite(BATTERY_ENABLE_PIN, HIGH);\n  delay(5);\n\n  // \u96FB\u5727\u3092\u30DF\u30EA\u30DC\u30EB\u30C8\u5358\u4F4D\u3067\u8AAD\u307F\u53D6\u308A\n  int mv = analogReadMilliVolts(BATTERY_ADC_PIN);\n\n  // \u30D0\u30C3\u30C6\u30EA\u30FC\u76E3\u8996\u3092\u7121\u52B9\u5316\n  digitalWrite(BATTERY_ENABLE_PIN, LOW);\n\n  // \u5B9F\u969B\u306E\u30D0\u30C3\u30C6\u30EA\u30FC\u96FB\u5727\u3092\u8A08\u7B97\uFF08\u5206\u5727\u56DE\u8DEF\u306B\u3088\u308A2\u500D\uFF09\n  float batteryVoltage = (mv / 1000.0) * 2;\n\n  // \u96FB\u5727\u3092\u5370\u5237\n  Serial1.print("\u30D0\u30C3\u30C6\u30EA\u30FC: ");\n  Serial1.print(batteryVoltage, 2);\n  Serial1.println(" V");\n\n  delay(2000);\n}\n'})}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Code Explanation:"})}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"GPIO1 reads the divided battery voltage through ADC"}),"\n",(0,t.jsx)(n.li,{children:"GPIO21 enables the battery monitoring circuit"}),"\n",(0,t.jsx)(n.li,{children:"The actual battery voltage is twice the measured voltage due to the voltage divider"}),"\n",(0,t.jsx)(n.li,{children:"For a fully charged LiPo battery, expect around 4.2V"}),"\n",(0,t.jsx)(n.li,{children:"When battery is low, voltage drops to around 3.3V"}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Expected Output"})}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{children:"\u30D0\u30C3\u30C6\u30EA\u30FC\u96FB\u5727\u30E2\u30CB\u30BF\u30FC\n\n\u30D0\u30C3\u30C6\u30EA\u30FC: 4.18 V\n\u30D0\u30C3\u30C6\u30EA\u30FC: 4.19 V\n\u30D0\u30C3\u30C6\u30EA\u30FC: 4.18 V\n"})}),"\n",(0,t.jsx)(n.h3,{id:"using-the-microsd-card",children:"Using the MicroSD Card"}),"\n",(0,t.jsx)(n.p,{children:"For applications requiring additional storage, such as a digital photo frame or data logging, the reTerminal E Series includes a MicroSD card slot."}),"\n",(0,t.jsx)(n.p,{children:"Insert a microSD card if you plan to use the device as a digital photo frame or need additional storage."}),"\n",(0,t.jsx)("div",{style:{textAlign:"center"},children:(0,t.jsx)("img",{src:"https://files.seeedstudio.com/wiki/reterminal_e10xx/img/133.jpg",style:{width:700,height:"auto"}})}),"\n",(0,t.jsx)(n.admonition,{type:"note",children:(0,t.jsxs)(n.p,{children:["The reTerminal E Series only supports MicroSD cards up to 64GB formatted with the ",(0,t.jsx)(n.strong,{children:"Fat32"})," file system."]})}),"\n",(0,t.jsx)(n.h4,{id:"basic-sd-card-operations-listing-files",children:"Basic SD Card Operations: Listing Files"}),"\n",(0,t.jsxs)(n.p,{children:["This example demonstrates how to initialize the SD card, detect when it is inserted or removed, and list all the files and directories in its root. The code is identical for both the ",(0,t.jsx)(n.strong,{children:"reTerminal E1001"})," and ",(0,t.jsx)(n.strong,{children:"reTerminal E1002"}),"."]}),"\n",(0,t.jsx)(n.p,{children:"\u4EE5\u4E0B\u306E\u30B3\u30FC\u30C9\u3092Arduino IDE\u30B9\u30B1\u30C3\u30C1\u306B\u30B3\u30D4\u30FC\u3057\u3066\u304F\u3060\u3055\u3044\u3002"}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-cpp",children:'#include <SD.h>\n#include <SPI.h>\n\n// SD Card Pin Definitions\n#define SD_EN_PIN   16  // Power enable for the SD card slot\n#define SD_DET_PIN  15  // Card detection pin\n#define SD_CS_PIN   14  // Chip Select for the SD card\n#define SD_MOSI_PIN 9   // Shared with ePaper Display\n#define SD_MISO_PIN 8\n#define SD_SCK_PIN  7   // Shared with ePaper Display\n\n// Serial configuration for reTerminal E Series\n#define SERIAL_RX 44\n#define SERIAL_TX 43\n\n// Use the HSPI bus for the SD card to avoid conflict with other peripherals\nSPIClass spiSD(HSPI);\n\n// Global variables to track SD card state\nbool sdMounted = false;\nbool lastCardPresent = false;\nunsigned long lastCheckMs = 0;\nconst unsigned long checkIntervalMs = 1000; // Check for card changes every second\n\n// Checks if a card is physically inserted.\n// The detection pin is LOW when a card is present.\nbool isCardInserted() {\n  return digitalRead(SD_DET_PIN) == LOW;\n}\n\n// Helper function to print indentation for directory listing\nvoid printIndent(uint8_t level) {\n  for (uint8_t i = 0; i < level; ++i) {\n    Serial1.print("  ");\n  }\n}\n\n// Recursively lists files and directories\nvoid listDir(File dir, uint8_t level) {\n  while (true) {\n    File entry = dir.openNextFile();\n    if (!entry) {\n      // No more entries in this directory\n      break;\n    }\n\n    printIndent(level);\n    if (entry.isDirectory()) {\n      Serial1.print("[DIR]  ");\n      Serial1.println(entry.name());\n      // Recurse into the subdirectory\n      listDir(entry, level + 1);\n    } else {\n      // It\'s a file, print its name and size\n      Serial1.print("[FILE] ");\n      Serial1.print(entry.name());\n      Serial1.print("  ");\n      Serial1.print(entry.size());\n      Serial1.println(" bytes");\n    }\n    entry.close();\n  }\n}\n\n// Opens the root directory and starts the listing process\nvoid listRoot() {\n  File root = SD.open("/");\n  if (!root) {\n    Serial1.println("[SD] Failed to open root directory.");\n    return;\n  }\n  if (!root.isDirectory()) {\n    Serial1.println("[SD] Root is not a directory.");\n    root.close();\n    return;\n  }\n  Serial1.println("[SD] Listing files in /");\n  listDir(root, 0);\n  root.close();\n}\n\n// Initializes the SPI bus and mounts the SD card\nbool mountSD() {\n  // Enable power to the SD card slot\n  pinMode(SD_EN_PIN, OUTPUT);\n  digitalWrite(SD_EN_PIN, HIGH);\n  delay(5);\n\n  // Initialize the HSPI bus with the correct pins for the SD card\n  spiSD.end(); // Guard against repeated begin calls\n  spiSD.begin(SD_SCK_PIN, SD_MISO_PIN, SD_MOSI_PIN, SD_CS_PIN);\n\n  // Attempt to mount the SD card file system\n  if (!SD.begin(SD_CS_PIN, spiSD)) {\n    Serial1.println("[SD] MicroSD initialization failed. Check card formatting.");\n    return false;\n  }\n  Serial1.println("[SD] MicroSD mounted successfully.");\n  return true;\n}\n\n// Unmounts the SD card by releasing the SPI bus\nvoid unmountSD() {\n  SD.end();\n  spiSD.end();\n  Serial1.println("[SD] MicroSD unmounted.");\n}\n\nvoid setup() {\n  // Start the secondary serial port for output\n  Serial1.begin(115200, SERIAL_8N1, SERIAL_RX, SERIAL_TX);\n  while (!Serial1) {\n    delay(10); // Wait for Serial1 to be ready\n  }\n\n  // Set up the card detection pin with an internal pull-up resistor\n  pinMode(SD_DET_PIN, INPUT_PULLUP);\n  // Set up the power enable pin\n  pinMode(SD_EN_PIN, OUTPUT);\n  digitalWrite(SD_EN_PIN, HIGH);\n\n  // Check for a card at startup\n  lastCardPresent = isCardInserted();\n  if (lastCardPresent) {\n    sdMounted = mountSD();\n    if (sdMounted) {\n      listRoot(); // If mounted, list files\n    }\n  } else {\n    Serial1.println("[SD] No card detected at startup. Please insert a card.");\n  }\n}\n\nvoid loop() {\n  // Periodically check for card insertion or removal without blocking the loop\n  unsigned long now = millis();\n  if (now - lastCheckMs >= checkIntervalMs) {\n    lastCheckMs = now;\n\n    bool present = isCardInserted();\n    if (present != lastCardPresent) {\n      lastCardPresent = present; // Update the state\n\n      if (present) {\n        Serial1.println("\\n[SD] Card inserted.");\n        if (!sdMounted) {\n          sdMounted = mountSD();\n        }\n        if (sdMounted) {\n          listRoot(); // List files upon insertion\n        }\n      } else {\n        Serial1.println("\\n[SD] Card removed.");\n        if (sdMounted) {\n          unmountSD();\n          sdMounted = false;\n        }\n      }\n    }\n  }\n  // You can place other non-blocking code here\n}\n'})}),"\n",(0,t.jsx)(n.h5,{id:"\u30B3\u30FC\u30C9\u306E\u8AAC\u660E",children:"\u30B3\u30FC\u30C9\u306E\u8AAC\u660E"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(